// NEONSTRIKE map: "VECTOR" — a CS-style three-lane arena.
// Boxes are [minX, minY, minZ, maxX, maxY, maxZ, materialId].
// Coordinates: y up, floor top at y=0. Arena spans x -41..41, z -31..31.

export const MAT = {
  FLOOR: 0,
  BRICK: 1,
  CRATE: 2,
  METAL: 3,
  NEON_CYAN: 4,
  NEON_MAGENTA: 5,
  DARKMETAL: 6,
  PLASTER: 7,
  BOT_BODY: 8,
  BOT_HEAD: 9,
  HAZARD: 10,
};

export const MATERIAL_NAMES = [
  'asphalt floor', 'brick wall', 'wood crate', 'brushed metal',
  'neon cyan strip', 'neon magenta strip', 'dark metal panel',
  'plaster wall', 'bot chassis', 'bot visor', 'hazard crate',
];

export const BOXES = [
  // Ground slab
  [-41, -1, -31, 41, 0, 31, MAT.FLOOR],

  // Outer walls
  [-41, 0, -32, 41, 7, -30, MAT.BRICK],   // north
  [-41, 0, 30, 41, 7, 32, MAT.BRICK],     // south
  [-42, 0, -32, -40, 7, 32, MAT.PLASTER], // west
  [40, 0, -32, 42, 7, 32, MAT.PLASTER],   // east

  // Mid corridor walls (door gap at z -2..4)
  [-6, 0, -18, -5, 4.5, -2, MAT.PLASTER],
  [-6, 0, 4, -5, 4.5, 18, MAT.PLASTER],
  [5, 0, -18, 6, 4.5, -2, MAT.BRICK],
  [5, 0, 4, 6, 4.5, 18, MAT.BRICK],

  // Long A corridor (east lane): inner wall, opens north of z -10
  [30, 0, -10, 31, 4.5, 24, MAT.BRICK],
  // Long B corridor (west lane)
  [-31, 0, -10, -30, 4.5, 24, MAT.PLASTER],

  // Site separator walls (gaps at |x| 6..12 are the connectors)
  [12, 0, -18, 30, 4.5, -17, MAT.DARKMETAL],   // A connector wall
  [-30, 0, -18, -12, 4.5, -17, MAT.DARKMETAL], // B connector wall

  // A site crates (NE)
  [33, 0, -26, 36, 2, -23, MAT.CRATE],
  [33, 2, -26, 35, 3.5, -24.5, MAT.CRATE],   // stacked
  [24, 0, -14, 27, 2.6, -11, MAT.HAZARD],
  [37, 0, -12, 39.5, 1.5, -9.5, MAT.CRATE],

  // B site crates (NW)
  [-36, 0, -27, -33, 2, -24, MAT.CRATE],
  [-26, 0, -13, -23, 2.5, -10, MAT.HAZARD],
  [-38, 0, -12, -35, 1.5, -9, MAT.CRATE],
  [-35.5, 2, -26.5, -33.5, 3.4, -24.8, MAT.CRATE], // stacked

  // Mid cover
  [-2, 0, -9, 2, 2, -6, MAT.METAL],
  [-9, 0, 20, -6, 1.5, 23, MAT.CRATE],
  [7, 0, 21, 10, 2, 24, MAT.HAZARD],

  // Lane entrance crates
  [34, 0, 18, 37, 2, 21, MAT.CRATE],
  [-37, 0, 16, -34, 2, 19, MAT.CRATE],

  // Site pillars
  [14, 0, -28, 16, 6, -26, MAT.DARKMETAL],
  [-16, 0, -28, -14, 6, -26, MAT.DARKMETAL],

  // Neon strips (emissive). Slightly proud of their parent walls.
  [-6.15, 3.0, -18, -4.85, 3.35, -2, MAT.NEON_CYAN],   // mid west N
  [-6.15, 3.0, 4, -4.85, 3.35, 18, MAT.NEON_CYAN],     // mid west S
  [4.85, 3.0, -18, 6.15, 3.35, -2, MAT.NEON_MAGENTA],  // mid east N
  [4.85, 3.0, 4, 6.15, 3.35, 18, MAT.NEON_MAGENTA],    // mid east S
  [29.85, 3.2, -8, 31.15, 3.55, 22, MAT.NEON_CYAN],    // long A
  [-31.15, 3.2, -8, -29.85, 3.55, 22, MAT.NEON_MAGENTA], // long B
  [-41.15, 4.2, -31.5, 41.15, 4.6, -29.85, MAT.NEON_CYAN],  // north wall band
  [-41.15, 4.2, 29.85, 41.15, 4.6, 31.5, MAT.NEON_MAGENTA], // south wall band
];

// Point lights: [x, y, z, r, g, b, intensity]
export const LIGHTS = [
  [33, 4.5, -15, 0.3, 0.9, 1.0, 26],    // A site cyan
  [-33, 4.5, -15, 1.0, 0.25, 0.9, 26],  // B site magenta
  [0, 5.2, 0, 0.9, 0.95, 1.0, 20],      // mid white
  [0, 4.5, 26, 1.0, 0.7, 0.35, 18],     // spawn warm
  [0, 4.8, -24, 0.6, 0.7, 1.0, 16],     // mid-north cool
  [20, 4.0, 22, 0.3, 0.9, 1.0, 10],     // SE accent
  [-20, 4.0, 22, 1.0, 0.25, 0.9, 10],   // SW accent
  // slot 7 reserved for muzzle flash (set per-frame)
  [0, -100, 0, 1.0, 0.85, 0.5, 0],
];

